using System;
using System.Linq;
using System.Reflection;
using System.Text.Json;
public static class Program {
 public static void Main(string[] args) {
  Assembly assembly=Assembly.LoadFrom(args[0]);
  MethodInfo method=assembly.GetType("SolidWorks.Interop.sldworks.IModelDocExtension",true).GetMethod("GetDependencies");
  Console.WriteLine(JsonSerializer.Serialize(new {
   assembly_full_name=assembly.FullName,
   declaring_type=method.DeclaringType.FullName,
   method=method.Name,return_type=method.ReturnType.FullName,
   parameters=method.GetParameters().Select(p=>new {position=p.Position,name=p.Name,type=p.ParameterType.FullName}).ToArray(),
   method_attributes=method.GetCustomAttributesData().Select(a=>a.ToString()).ToArray(),
   return_attributes=method.ReturnParameter.GetCustomAttributesData().Select(a=>a.ToString()).ToArray(),
   application_or_COM_method_executed=false
  }));
 }
}

